T? _workshopFirstOrNull<T>(Iterable<T> values) => values.isEmpty ? null : values.first;

class CheWorkshopRoom extends StatefulWidget{
 const CheWorkshopRoom({super.key,required this.client,required this.active,this.focusAgent,this.onSpeak,this.onOpenRoom});
 final CheAgentRuntimeClient client;final bool active;final String? focusAgent;final Future<void> Function(String)? onSpeak;final void Function(int)? onOpenRoom;
 @override State<CheWorkshopRoom> createState()=>_CheWorkshopRoomState();
}
class _CheWorkshopRoomState extends State<CheWorkshopRoom>{
 Map<String,dynamic> _data=const{};Timer? _timer;bool _loading=true,_narrated=false;String? _shownFocus;
 List<Map<String,dynamic>> get _pieces=>(_data['pieces']as List? ?? const[]).whereType<Map>().map((e)=>Map<String,dynamic>.from(e)).toList();
 @override void initState(){super.initState();_sync();_poll();}
 @override void didUpdateWidget(covariant CheWorkshopRoom old){super.didUpdateWidget(old);if(old.active!=widget.active)_poll();if(old.focusAgent!=widget.focusAgent){_shownFocus=null;_focusCode();}}
 void _poll(){_timer?.cancel();if(widget.active)_timer=Timer.periodic(const Duration(seconds:8),(_)=>_sync(silent:true));}
 Future<void> _sync({bool silent=false})async{try{final next=await widget.client.workshop();if(!mounted)return;setState((){_data=next;_loading=false;});final s='${next['summary']??''}'.trim();if(!silent&&!_narrated&&s.isNotEmpty&&widget.active){_narrated=true;await widget.onSpeak?.call(s);}await _focusCode();}catch(_){if(mounted)setState(()=>_loading=false);}}
 Future<void> _focusCode()async{final f=widget.focusAgent?.trim().toLowerCase();if(f==null||f.isEmpty||f==_shownFocus||!mounted)return;final p=_workshopFirstOrNull(_pieces.where((x)=>'${x['who']}'.toLowerCase().contains(f)&&('${x['code']}'.trim().isNotEmpty||'${x['diff']}'.trim().isNotEmpty)));if(p==null)return;_shownFocus=f;WidgetsBinding.instance.addPostFrameCallback((_){if(mounted)_showPiece(p,codeFirst:true);});}
 Future<void> _showPiece(Map<String,dynamic> p,{bool codeFirst=false})async{final code='${p['diff']??''}'.trim().isNotEmpty?'${p['diff']}':'${p['code']??''}',link='${p['link']??''}'.trim();if(codeFirst&&code.trim().isNotEmpty){await showModalBottomSheet<void>(context:context,isScrollControlled:true,backgroundColor:CheColors.surface,builder:(c)=>SafeArea(child:SizedBox(height:MediaQuery.sizeOf(c).height*.78,child:Column(children:[ListTile(title:Text('${p['who']} · ${p['title']}',style:CheType.label),subtitle:const Text('Actual code or diff.',style:CheType.caption),trailing:IconButton(icon:const Icon(Icons.close),onPressed:()=>Navigator.pop(c))),Expanded(child:Semantics(label:'Code written by ${p['who']}',child:SingleChildScrollView(padding:const EdgeInsets.all(16),child:SelectableText(code,style:const TextStyle(fontFamily:'monospace',fontSize:13,height:1.4)))))]))));return;}if(link.isNotEmpty){final u=Uri.tryParse(link);if(u!=null)await launchUrl(u,mode:LaunchMode.inAppBrowserView);}else if(code.trim().isNotEmpty){await _showPiece(p,codeFirst:true);}}
 Future<void> _editLook(Map<String,dynamic>a)async{const choices=<String,List<String>>{'body_type':['compact','standard','tall'],'face':['round','oval','square'],'skin_tone':['deep','brown','warm','tan','golden','light'],'hair':['close','fade','waves','curls','braids','locs','bun','bald'],'eyes':['dark','brown','hazel','green','blue'],'outfit':['che','suit','jacket-red','jacket-teal','hoodie','studio','tech'],'accessory':['none','glasses','headset','chain','hat'],'animation':['calm','focused','confident','walking']};final avatars=Map<String,dynamic>.from(_data['avatars']as Map? ?? const{}),look=<String,String>{};final cur=avatars['${a['id']}'];if(cur is Map){for(final e in cur.entries){if(e.value is String)look['${e.key}']='${e.value}';}}final saved=await showModalBottomSheet<Map<String,String>>(context:context,isScrollControlled:true,backgroundColor:CheColors.surface,builder:(c)=>StatefulBuilder(builder:(c,setSheet)=>SafeArea(child:SingleChildScrollView(padding:EdgeInsets.fromLTRB(18,16,18,24+MediaQuery.viewInsetsOf(c).bottom),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Text('Character creator · ${a['name']}',style:CheType.title),const Text('Original CHE procedural parts only.',style:CheType.caption),const SizedBox(height:12),for(final e in choices.entries)Semantics(label:'${e.key.replaceAll('_',' ')} for ${a['name']}',child:DropdownButtonFormField<String>(initialValue:e.value.contains(look[e.key])?look[e.key]:e.value.first,decoration:InputDecoration(labelText:e.key.replaceAll('_',' ')),items:[for(final v in e.value)DropdownMenuItem(value:v,child:Text(v.replaceAll('-',' ')))],onChanged:(v)=>setSheet(()=>look[e.key]=v??e.value.first))),const SizedBox(height:16),FilledButton(onPressed:()=>Navigator.pop(c,{for(final e in choices.entries)e.key:look[e.key]??e.value.first}),child:const Text('Save look'))])))));if(saved==null)return;await widget.client.saveWorkshopAvatar('${a['id']}',saved);await _sync(silent:true);await widget.onSpeak?.call('${a['name']} has the new look, sir.');}
 void _tap(String id){if(id.startsWith('work:')){final raw=id.substring(5),p=_workshopFirstOrNull(_pieces.where((x)=>'${x['id']}'==raw));if(p!=null)_showPiece(p,codeFirst:'${p['code']}'.isNotEmpty||'${p['diff']}'.isNotEmpty);return;}if(id.startsWith('agent:')){final raw=id.substring(6),a=_workshopFirstOrNull((_data['agents']as List? ?? const[]).whereType<Map>().where((x)=>'${x['id']}'==raw));if(a!=null)_editLook(Map<String,dynamic>.from(a));return;}if(id=='door:theater')widget.onOpenRoom?.call(8);if(id=='door:music')widget.onOpenRoom?.call(4);if(id=='door:art')widget.onOpenRoom?.call(5);}
 @override void dispose(){_timer?.cancel();super.dispose();}
 @override Widget build(BuildContext context){if(_loading)return const Center(child:CircularProgressIndicator());final agents=(_data['agents']as List? ?? const[]).whereType<Map>().toList(),summary='${_data['summary']??'Workshop is quiet.'}';return RefreshIndicator(onRefresh:_sync,child:ListView(physics:const AlwaysScrollableScrollPhysics(),padding:const EdgeInsets.all(12),children:[Row(children:[Expanded(child:Semantics(liveRegion:true,child:Text(summary,style:CheType.body))),IconButton(tooltip:'Read Workshop status aloud',onPressed:()=>widget.onSpeak?.call(summary),icon:const Icon(Icons.volume_up_rounded))]),const SizedBox(height:8),ValueListenableBuilder<CheSceneQuality>(valueListenable:CheSceneQualityStore.value,builder:(context,quality,_)=>CheNativeSceneWorld(mode:CheSceneMode.workshop,quality:quality,height:390,semanticsLabel:'Immersive native Workshop. Real Office work only.',entities:[for(final a in agents)CheSceneEntity(id:'agent:${a['id']}',label:'${a['name']}',description:'${a['status']}',color:CheColors.accent,state:'${a['status']}'),for(final p in _pieces.take(10))CheSceneEntity(id:'work:${p['id']}',label:'${p['title']}',description:'${p['who']}. ${p['status']}',color:p['finished']==true?CheColors.success:CheColors.warning,state:'${p['status']}')],onEntityTap:_tap)),const SizedBox(height:8),Wrap(spacing:8,children:[OutlinedButton.icon(onPressed:()=>widget.onOpenRoom?.call(8),icon:const Icon(Icons.theaters_outlined),label:const Text('Theater')),OutlinedButton.icon(onPressed:()=>widget.onOpenRoom?.call(4),icon:const Icon(Icons.music_note_outlined),label:const Text('Music')),OutlinedButton.icon(onPressed:()=>widget.onOpenRoom?.call(5),icon:const Icon(Icons.palette_outlined),label:const Text('Art'))]),const SizedBox(height:10),Text('CREW LOOKS',style:CheType.overline),SizedBox(height:62,child:ListView.separated(scrollDirection:Axis.horizontal,itemCount:agents.length,separatorBuilder:(_,_)=>const SizedBox(width:8),itemBuilder:(_,i){final a=agents[i];return Semantics(button:true,label:'Customize ${a['name']}. ${a['status']}.',child:ActionChip(avatar:const Icon(Icons.person_outline,size:18),label:Text('${a['name']}'),onPressed:()=>_editLook(Map<String,dynamic>.from(a))));})),Text('REAL WORK',style:CheType.overline),if(_pieces.isEmpty)const Padding(padding:EdgeInsets.all(18),child:Text('No real work objects to show right now.',style:CheType.bodyDim))else for(final p in _pieces.take(40))Semantics(button:true,label:'${p['who']}. ${p['title']}. Status ${p['status']}.${p['progress']==null?'':' Progress ${p['progress']} percent.'}',child:ListTile(leading:Icon(p['finished']==true?Icons.emoji_events_outlined:Icons.blur_circular_rounded,color:p['finished']==true?CheColors.warning:CheColors.accent),title:Text('${p['who']} · ${p['title']}',maxLines:2,overflow:TextOverflow.ellipsis,style:CheType.label),subtitle:Text('${p['status']}${p['progress']==null?'':' · ${p['progress']}%'}',style:CheType.caption),trailing:const Icon(Icons.chevron_right),onTap:()=>_showPiece(p,codeFirst:'${p['code']}'.isNotEmpty||'${p['diff']}'.isNotEmpty)))]));}
}
